/* JavaScript Node ACM模式 控制台输入获取 */
const path = require("path");
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    n = parseInt(lines[0]);
  }

  if (n && lines.length === n + 2) {
    lines.shift();
    const str = lines.pop();

    const grid = lines.map((line) => line.split(","));

    console.log(findLetter(grid, n, str));

    lines.length = 0;
  }
});

function findLetter(grid, n, str) {
  function dfs(i, j, k, path) {
    if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] !== str[k])
      return false;

    path.push([i, j]);
    if (path.length === str.length) return true;

    const tmp = grid[i][j];
    grid[i][j] = undefined;

    const res =
      dfs(i - 1, j, k + 1, path) ||
      dfs(i + 1, j, k + 1, path) ||
      dfs(i, j - 1, k + 1, path) ||
      dfs(i, j + 1, k + 1, path);

    if (!res) {
      grid[i][j] = tmp;
      path.pop();
    }

    return res;
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const path = [];
      if (dfs(i, j, 0, path)) {
        return path.toString();
      }
    }
  }

  return "N";
}

