def dfs(i, j, k, path):
    if i < 0 or i >= n or j < 0 or j >= n or matrix[i][j] != tar[k]:
        return False

    path.append([i, j])
    if len(path) == len(tar):
        return True

    tmp = matrix[i][j]
    matrix[i][j] = ""

    res = dfs(i - 1, j, k + 1, path) or dfs(i + 1, j, k + 1, path) or dfs(i, j - 1, k + 1, path) or dfs(i, j + 1, k + 1, path)

    if not res:
        matrix[i][j] = tmp
        path.pop()

    return res


